<script setup>
import {companyTime} from './company-model.js';
import './inquiries.css';
defineProps({entry:Object,modelValue:String,busy:Boolean,loading:Boolean,visitor:Boolean,canReply:{type:Boolean,default:true}});
const emit=defineEmits(['update:modelValue','reply','refresh']);
</script>
<template><section class="site-inquiry-conversation" :aria-busy="busy || loading"><p v-if="loading" class="read-loading" role="status">جارٍ تحميل المحادثة…</p><template v-else-if="entry"><header class="site-inquiry-heading"><div><h2>{{visitor?'متابعة رسالتك':entry.name}}</h2><small v-if="!visitor" dir="auto">{{entry.contact}}</small></div><div class="actions"><span class="badge">{{entry.status==='new'?'بانتظار الرد':'تمت المتابعة'}}</span><button type="button" class="btn small" :disabled="busy" @click="emit('refresh')">تحديث الردود</button></div></header><div class="site-inquiry-history" aria-label="سجل الرسالة والردود"><article class="site-inquiry-bubble visitor"><b>{{visitor?'رسالتك':'رسالة الزبون'}}</b><p dir="auto">{{entry.message}}</p><small>{{companyTime(entry.time)}}</small></article><article v-for="message in entry.messages" :key="message.id" class="site-inquiry-bubble" :class="message.sender"><b>{{message.sender==='staff'?'إدارة الشركة':visitor?'أنت':'الزبون'}}</b><p dir="auto">{{message.body}}</p><small>{{companyTime(message.time)}}</small></article></div><form v-if="canReply" class="site-inquiry-reply" @submit.prevent="emit('reply')"><label>الرد<textarea :value="modelValue" required maxlength="3000" rows="3" :disabled="busy" @input="emit('update:modelValue',$event.target.value)"/></label><button class="btn primary" :disabled="busy || !modelValue?.trim()">{{busy?'جارٍ الإرسال…':'إرسال الرد'}}</button></form></template><p v-else class="empty">اختر رسالة لعرض تفاصيلها والرد عليها.</p></section></template>
